// The README's "A real run" section is generated by scripts/readme-run.mjs
// from the current CLI and hooks. These tests fail when the README's copy
// drifts from what the CLI prints, and check the run leaves this repo alone.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync, execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdtempSync, realpathSync, rmSync, existsSync, readdirSync, statSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SCRIPT = join(ROOT, 'scripts', 'readme-run.mjs');
const run = (...args) => spawnSync('node', [SCRIPT, ...args], { cwd: ROOT, encoding: 'utf8', env: { ...process.env, CLAUDE_PROJECT_DIR: ROOT } });

test('the README run section matches what the current CLI prints', () => {
  const r = run('--check');
  assert.equal(r.status, 0, r.stdout + r.stderr);
});

test('the check fails when the README section is edited', () => {
  const dir = realpathSync(mkdtempSync(join(tmpdir(), 'jig-readme-')));
  try {
    const copy = join(dir, 'README.md');
    const text = readFileSync(join(ROOT, 'README.md'), 'utf8');
    const start = text.indexOf('<!-- run:start -->');
    assert.ok(start > -1, 'README has a run:start marker');
    writeFileSync(copy, text.replace(/PASS C1/, 'PASS C9'));
    assert.notEqual(readFileSync(copy, 'utf8'), text, 'the edit landed');
    assert.equal(run('--check', '--readme', copy).status, 1);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test('the run shows each thing it claims, from real output', () => {
  const text = readFileSync(join(ROOT, 'README.md'), 'utf8');
  const section = text.slice(text.indexOf('<!-- run:start -->'), text.indexOf('<!-- run:end -->'));
  for (const want of [/is protected by check C1/, /A new dependency is a one-way door/, /outside S1's Touch list/, /FAIL C1/, /"?block"?/, /PASS C1/, /Verified: S1 C1 pass \(tree [0-9a-f]{7}\)/]) {
    assert.match(section, want);
  }
});

test("generating the run doesn't touch this repo's .git/jig", () => {
  const gitDir = execFileSync('git', ['rev-parse', '--absolute-git-dir'], { cwd: ROOT, encoding: 'utf8' }).trim();
  const jigDir = join(gitDir, 'jig');
  const snap = () => (existsSync(jigDir) ? readdirSync(jigDir, { recursive: true }).map((f) => {
    const p = join(jigDir, String(f));
    return `${f}:${statSync(p).isFile() ? readFileSync(p, 'utf8').length : 'dir'}`;
  }).sort().join('\n') : '');
  const before = snap();
  const dir = realpathSync(mkdtempSync(join(tmpdir(), 'jig-readme-')));
  try {
    const copy = join(dir, 'README.md');
    writeFileSync(copy, readFileSync(join(ROOT, 'README.md'), 'utf8'));
    assert.equal(run('--readme', copy).status, 0);
  } finally { rmSync(dir, { recursive: true, force: true }); }
  assert.equal(snap(), before);
});
